import { test, expect } from '@playwright/test';

test.describe('User Profile - Timezone Settings', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile/settings');
    await page.getByRole('button', { name: 'Login' }).click();
    await page.getByLabel('Email').fill('user@example.com');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: 'Submit' }).click();
  });

  test('should display current timezone', async ({ page }) => {
    const timezoneDisplay = await page.getByText('Current Timezone:');
    await expect(timezoneDisplay).toBeVisible();
    const currentTimezone = await timezoneDisplay.nextSibling();
    await expect(currentTimezone).toHaveText('UTC');
  });

  test('should allow user to change timezone', async ({ page }) => {
    await page.getByLabel('Timezone').selectOption('America/New_York');
    await page.getByRole('button', { name: 'Save Changes' }).click();

    const successMessage = await page.getByText('Timezone updated successfully');
    await expect(successMessage).toBeVisible();

    const updatedTimezone = await page.getByText('Current Timezone:').nextSibling();
    await expect(updatedTimezone).toHaveText('America/New_York');
  });
});
